def wrap_code(*, parts: list[dict], var: str = "bb_wrap") -> str:
    """Snippet of the code node that chooses the words ending a call: each part is {"when": [[VAR, OP,
    VALUE?], ...], "say": TEXT}; the texts of the parts whose conditions hold are joined, in order, into
    `var` (say it with on_enter=wf.say("{{" + var + "}}")). The last part must hold always ("when": [])
    and carry the closing phrase; that text is also the fallback."""
    from builder.lib.hooks import check_conditions
    check_var(var)
    if not isinstance(parts, (list, tuple)) or not parts:
        raise ValueError("parts must be a non-empty list of {'when': [...], 'say': TEXT}")
    for index, part in enumerate(parts):
        if not isinstance(part, dict) or set(part) - {"when", "say"} or not isinstance(part.get("say"), str) \
                or not part.get("say").strip():
            raise ValueError("parts[" + str(index) + "] needs 'say' (a sentence) and may have 'when'")
        if part.get("when"):
            check_conditions(part["when"], "parts[" + str(index) + "].when")
    if parts[-1].get("when"):
        raise ValueError("the last part must hold always (no 'when'): the closing phrase")
    cfg = {"parts": [{"when": list(p.get("when") or []), "say": p["say"]} for p in parts], "var": var,
           "fallback": parts[-1]["say"]}
    check_no_double_braces(cfg)
    return embed.snippet(("common", "wrap"), "run_wrap", cfg, "code")


def list_code(*, node: str, tool: str, list_path: str, id_field: str, item_fields: list[str], var: str,
              empty: str = "", same_fields: list[str] | tuple = ()) -> str:
    """Code node snippet: the list at `list_path` of api_request node `node` (tool `tool`) as plain lines
    in variable `var` ('1. field: value; field: value', one item per line) and its length in `var`_count.

    Use it right after the api_request node whenever a later prompt needs a list or an object: the engine
    does not store a list under a response_mapping variable (measured: a mapped list stayed unset while a
    mapped number arrived), only as flattened keys, which this reads.
    list_path: the list's path inside the API body, dots for nesting (e.g. "data.items" for
        {"data": {"items": [...]}}). id_field: a field every item has. item_fields: the fields to write.
    same_fields: fields the caller picks an item by (a name, a short number): a line whose value other
        items share ends with ' (same F as items 2, 3)', so the model asks instead of picking one.
    """
    check_var(var)
    for name in (node, tool):
        if not NAME.match(name or ""):
            raise ValueError(f"node and tool must be plain names, not {name!r}")
    parts = [p for p in str(list_path).split(".") if p]
    if not parts:
        raise ValueError("list_path names the list inside the API body, e.g. 'data.items'")
    fields = list(item_fields)
    if id_field not in fields:
        fields.insert(0, id_field)
    path = ".".join(parts)
    cfg = {"sources": [node + "_response.data." + path, tool + "_response.data." + path],
           "list_field": parts[-1], "id_field": id_field, "item_fields": fields, "var": var, "empty": empty,
           "same_fields": [f for f in same_fields if f in fields]}
    if len(cfg["same_fields"]) != len(list(same_fields)):
        raise ValueError("every same_fields entry must be one of item_fields")
    check_no_double_braces(cfg)
    return embed.snippet(("common", "products", "lists"), "run_list", cfg, "code")
