{
  "openapi": "3.0.3",
  "info": {
    "title": "Freya Bank voice assistant: statement and debt services",
    "version": "2026-10-01",
    "description": "From the service contract of 1 October 2026 (Mert Koç), section 5. Every service is POST, JSON in and out. Request body = {\"data\": {service fields}, \"call\": {\"ani\": ..., \"lang\": \"tr\"}}. Response = {\"data\": {...}, \"result\": {...}}; success = HTTP 200 and result.returnCode \"1\". Error answers have no data object, only result (code, type ERROR or WARNING). Dates are strings dd.MM.yyyy, amounts JSON numbers. Checked against the mock on 11 Oct 2026."
  },
  "servers": [{"url": "https://yc-bank-mock.ustatech.workers.dev/voice/v1"}],
  "components": {
    "schemas": {
      "Call": {
        "type": "object",
        "description": "Call metadata the bank logs; nothing depends on it.",
        "properties": {
          "ani": {"type": "string", "description": "Caller's number"},
          "lang": {"type": "string", "description": "Language, tr"}
        }
      },
      "Result": {
        "type": "object",
        "properties": {
          "guid": {"type": "string"},
          "returnCode": {"type": "string", "description": "\"1\" = success; otherwise the error code"},
          "messageText": {"type": "string", "description": "For logs only, never read out"},
          "code": {"type": "string"},
          "message": {"type": "string"},
          "type": {"type": "string", "nullable": true, "description": "null on success, ERROR or WARNING on errors"}
        }
      },
      "DebtBlock": {
        "type": "object",
        "description": "One currency block. A block can be missing (the card does not carry that currency).",
        "properties": {
          "statementPaymentStatus": {"type": "string", "enum": ["HAS_DEBT", "NO_DEBT"]},
          "transferAmount": {"type": "number", "description": "Carried over from the previous period"},
          "statementDebt": {"type": "number", "description": "Statement debt"},
          "minPayment": {"type": "number", "description": "Minimum payment on the statement"},
          "remainingDebt": {"type": "number", "description": "What is left of the statement debt after payments since"},
          "remainingMinPayment": {"type": "number", "description": "What is left of the minimum payment"},
          "currentPeriodExpense": {"type": "number", "description": "Spending after the statement"},
          "totalDebt": {"type": "number", "description": "Total debt incl. spending after the statement; negative = credit balance"},
          "totalDebtPaymentStatus": {"type": "string", "enum": ["HAS_DEBT", "NO_DEBT"]},
          "remainAutomaticPaymentAmount": {"type": "number", "description": "Only meaningful when automaticPaymentFlag is Y"}
        }
      },
      "Error": {
        "type": "object",
        "description": "Error answer: no data object, only result.",
        "properties": {"result": {"$ref": "#/components/schemas/Result"}}
      }
    }
  },
  "paths": {
    "/cards.list": {
      "post": {
        "operationId": "cards_list",
        "summary": "The customer's eligible credit cards (customer number in).",
        "requestBody": {
          "required": true,
          "content": {"application/json": {"schema": {
            "type": "object",
            "required": ["data"],
            "properties": {
              "data": {
                "type": "object",
                "required": ["customerNo"],
                "properties": {
                  "customerNo": {"type": "string", "description": "8-digit customer number from the phone menu (string or number accepted)"},
                  "aiFlow": {"type": "string", "description": "Use case asking; CardOps for this one"}
                }
              },
              "call": {"$ref": "#/components/schemas/Call"}
            }
          }}}
        },
        "responses": {
          "200": {
            "description": "Cards. data.cards[]: cardNumber (masked in test: first 6 + last 4), cardNumberLast4, productName (free text, may be empty), status (A), isMainCard (false = not the customer's own main card); data.validCardsCount; data.exitState 1_CARD or MULTI_CARD.",
            "content": {"application/json": {"schema": {
              "type": "object",
              "properties": {
                "data": {
                  "type": "object",
                  "properties": {
                    "cards": {"type": "array", "items": {"type": "object", "properties": {
                      "cardNumber": {"type": "string"},
                      "cardNumberLast4": {"type": "string"},
                      "productName": {"type": "string"},
                      "status": {"type": "string"},
                      "isMainCard": {"type": "boolean"}
                    }}},
                    "validCardsCount": {"type": "integer"},
                    "exitState": {"type": "string", "enum": ["1_CARD", "MULTI_CARD"]}
                  }
                },
                "result": {"$ref": "#/components/schemas/Result"}
              }
            }}}
          },
          "404": {"description": "FB_IVR_CHANNEL_102 WARNING: customer has no valid card (Müşteriye ait geçerli kart bilgisi bulunamadı.). Not a broken service.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Error"}}}},
          "500": {"description": "FBE00099 ERROR: technical error (Teknik hata: ABORTED: )", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Error"}}}}
        }
      }
    },
    "/cards.balance": {
      "post": {
        "operationId": "cards_balance",
        "summary": "Statement and due dates and the debt per currency of one card.",
        "requestBody": {
          "required": true,
          "content": {"application/json": {"schema": {
            "type": "object",
            "required": ["data"],
            "properties": {
              "data": {
